// Découpe un texte de `length` caractères en fenêtres [début, fin].
// TODO : le pas doit être (size - overlap), pas `size` — sinon aucun
//        recouvrement, et une idée à cheval sur deux chunks est perdue.
export function chunkWindows({ length, size, overlap }) {
  const out = [];
  for (let start = 0; start < length; start += size) {
    out.push([start, Math.min(start + size, length)]);
  }
  return out;
}

